/* ==============================================================
   Rainmaker X · app · back office
   Rep Desk, staff passcode gate, not-found page, the admin pages (Overview, Verifications,
   Compliance forms, Requests, Orders, Companies, Messages, Clients, Audit) and the client page.
   ============================================================== */
'use strict';

// Rep Desk: requests to work, settling orders, quotes, client notes.
function viewDesk(main) {
  const st = D.marketStats(); const stl = D.allSettlements(); const open = stl.filter(x => !D.settlementDone(x)); const mrows = D.matchRecords(); const pendM = mrows.filter(r => r.status === 'pending');
  const desk = D.deskTrades(); const captured = desk.reduce((s_, t) => s_ + t.capture, 0);
  const demand = D.COMPANIES.map(c => ({ c, s: D.ioiSummary(c.id), asks: D.liveListings(c.id).length, bids: D.liveBids(c.id).length })).sort((a, b) => (b.s.buys + b.s.sells) - (a.s.buys + a.s.sells)).slice(0, 10);
  const clients = D.CLIENTS.map(cl => Object.assign({}, cl)); clients[0].status = D.profile().verification; clients[0].type = D.profile().investorType || 'accredited';
  const badge = s_ => s_ === 'verified' ? '<span class="badge verified">Verified</span>' : s_ === 'pending' ? '<span class="badge pending">Pending review</span>' : '<span class="badge status">Unverified</span>';
  main.innerHTML = `<div class="page">
    ${pageHead({ icon: PH.desk, title: 'Rep Desk', tag: 'Internal', sub: 'What a registered representative sees: open orders, settlements waiting on paperwork, the client book, and where demand is building.', actions: `<a class="btn sm" href="#/admin">Open the console</a><a class="btn outline sm" href="#/representatives">Representatives</a>` })}
    <div class="tiles"><div class="card tile"><span class="label dim">Live asks</span><div class="v">${st.asks}</div><div class="small muted">${compact(st.askValue)} offered</div></div><div class="card tile"><span class="label dim">Live bids</span><div class="v">${st.bids}</div><div class="small muted">${compact(st.bidValue)} demand</div></div><div class="card tile"><span class="label dim">Matches</span><div class="v">${pendM.length}</div><div class="small muted">awaiting approval · ${open.length} settling</div></div><div class="card tile"><span class="label dim">Desk spread captured</span><div class="v up">${money(captured, 0)}</div><div class="small muted">${desk.length} principal trades</div></div></div>
    <div class="dash" style="grid-template-columns: minmax(0,1.3fr) minmax(0,1fr)">
      <div class="stack">
        ${(() => { const rq = D.requests().filter(r => r.status === 'pending'); return `<div class="card"><div class="card-head"><span class="label">Requests from members awaiting verification</span><span class="badge ${rq.length ? 'pending' : 'status'}">${rq.length} open</span></div>${rq.length ? `<table class="table compact"><thead><tr><th>Request</th><th>Client</th><th>What</th><th>Submitted</th></tr></thead><tbody>${rq.map(r => `<tr><td><span class="oid">${esc(r.id)}</span></td><td>${esc(D.profile().name)} <span class="tiny muted">${esc(D.profile().verification)}</span></td><td>${esc(r.what)}</td><td>${fmtPlaced(r.created)}</td></tr>`).join('')}</tbody></table><div class="card-foot small">Work these off the book. They are placed automatically when compliance approves the client (<a class="link" href="#/profile/verification">simulate approval</a>).</div>` : '<div class="card-body small muted">No pending requests.</div>'}</div>`; })()}
        <div class="card"><div class="card-head"><span class="label">Matches</span><span class="muted small">${pendM.length} awaiting approval · ${open.length} settling · <a class="link" href="#/admin/matches">Matches queue</a></span></div>${matchesTable(mrows.filter(r => r.label !== 'Completed').slice(0, 12), { staff: true, empty: 'No open matches.' })}</div>
        <div class="card"><div class="card-head"><span class="label">Demand map · indications of interest</span><a class="link small" href="#/browse">Browse</a></div><table class="table compact"><thead><tr><th>Company</th><th class="num">Buyers</th><th class="num">Top buy price</th><th class="num">Sellers</th><th class="num">Low sell price</th><th class="num">RX price</th><th class="num">Asks / Bids</th></tr></thead><tbody>${demand.map(d => `<tr class="clickable" data-href="#/company/${d.c.id}"><td><span class="row">${logo(d.c, 'sm')}<b>${esc(d.c.name)}</b></span></td><td class="num strong">${d.s.buys}</td><td class="num">${money(d.s.topBuy)}</td><td class="num strong">${d.s.sells}</td><td class="num">${money(d.s.lowSell)}</td><td class="num">${money(D.price(d.c.id))}</td><td class="num">${d.asks} / ${d.bids}</td></tr>`).join('')}</tbody></table></div>
      </div>
      <div class="stack">
        ${(() => { const rr = D.pendingRepRequests(); return `<div class="card"><div class="card-head"><span class="label">Primary representative requests</span><span class="badge ${rr.length ? 'pending' : 'status'}">${rr.length} waiting</span></div>${rr.length ? `<table class="table compact"><tbody>${rr.map(r => `<tr><td><a class="link" href="#/client/${esc(r.clientId)}"><b>${esc(r.clientName)}</b></a><div class="tiny muted">${esc(D.rep(r.from).name)} → <b>${esc(D.rep(r.to).name)}</b> · ${esc(r.by.replace('staff:', ''))} · ${fmtDateShort(r.ts)}</div></td><td class="num"><span class="row" style="justify-content:flex-end;gap:6px"><button class="btn bid sm" type="button" data-rr-approve="${esc(r.id)}">Accept</button><button class="btn danger sm" type="button" data-rr-deny="${esc(r.id)}">Deny</button></span></td></tr>`).join('')}</tbody></table><div class="card-foot small">A member or an administrator proposed you as primary representative. Accepting moves the client, their orders and settlements to you.</div>` : '<div class="card-body muted small">No one is waiting to be taken on.</div>'}</div>`; })()}
        <div class="card"><div class="card-head"><span class="label">Client book</span><span class="muted small">${clients.filter(x => x.status === 'pending').length} awaiting compliance</span></div><table class="table compact"><thead><tr><th>Client</th><th>Type</th><th>Status</th><th>Rep</th></tr></thead><tbody>${clients.map(cl => `<tr><td><b>${esc(cl.name)}</b>${cl.aum ? `<div class="tiny muted">${compact(cl.aum)} on platform</div>` : ''}</td><td class="small">${esc(D.INVESTOR_TYPES[cl.type].split(' (')[0])}</td><td>${badge(cl.status)}</td><td class="small">${esc(D.rep(cl.rep).name.split(' ')[0])}</td></tr>`).join('')}</tbody></table></div>
        <div class="card"><div class="card-head"><span class="label">Client inbox</span><span class="muted small">Messages from ${esc(D.profile().name)}</span></div><div class="card-body stack" style="gap:10px">${(() => { const mine = D.messages().filter(m => m.from === 'you').slice(-4).reverse(); return mine.length ? mine.map(m => { const c = m.companyId ? D.company(m.companyId) : null; return `<div class="inbox-item"><div class="small"><b>${c ? esc(c.name) : 'General'}${m.orderId ? ' · ' + esc(m.orderId) : ''}</b> · ${fmtPlaced(m.ts)}</div><div class="small" style="margin:4px 0 8px">${esc(m.text)}</div><form class="row" data-reply="${esc(m.key)}" data-company="${m.companyId || ''}" data-order="${m.orderId || ''}"><input class="mini" name="text" placeholder="Reply as ${esc(D.rep(D.profile().rep).name.split(' ')[0])}…" style="flex:1" required><button class="btn sm dark" type="submit">Reply</button></form></div>`; }).join('') : '<div class="muted small">No client messages yet.</div>'; })()}</div></div>
        <div class="card"><div class="card-head"><span class="label">Desk activity</span><span class="muted small">Principal trades</span></div>${desk.length ? `<table class="table compact"><thead><tr><th>Company</th><th>Side</th><th class="num">Qty</th><th class="num">Price</th><th class="num">Captured</th></tr></thead><tbody>${desk.slice(0, 8).map(t => { const c = D.company(t.companyId); return `<tr><td>${esc(c.name)}</td><td>${t.side === 'buy' ? 'Sold to client' : 'Bought from client'}</td><td class="num">${num(t.qty)}</td><td class="num">${money(t.price)}</td><td class="num up">${money(t.capture, 0)}</td></tr>`; }).join('')}</tbody></table>` : '<div class="card-body muted small">No desk trades yet.</div>'}</div>
        <div class="card"><div class="card-head"><span class="label">Alerts armed by clients</span></div>${D.alerts().length ? `<table class="table compact"><tbody>${D.alerts().map(a => { const c = D.company(a.companyId); return `<tr><td>${esc(c.name)}</td><td class="small">${esc(D.ALERT_TYPES[a.type])} ${money(a.price)}</td><td>${a.triggered ? '<span class="badge verified">Fired</span>' : '<span class="badge status">Armed</span>'}</td></tr>`; }).join('')}</tbody></table>` : '<div class="card-body muted small">None.</div>'}</div>
      </div>
    </div></div>`;
  main.querySelectorAll('[data-reply]').forEach(f => f.addEventListener('submit', e => { e.preventDefault(); D.sendMessage({ companyId: f.dataset.company || null, orderId: f.dataset.order || null, text: f.text.value.trim(), from: 'rep' }); toast('Reply sent to client'); render(); }));
}


// Not found (also what non-staff see for staff routes).
function viewNotFound(main) { main.innerHTML = `<div class="page narrow" style="max-width:560px"><div class="card card-body stack"><h2>Page not found</h2><p class="muted" style="margin:0">There is nothing at this address.</p><div class="row"><a class="btn sm" href="#/dashboard">Dashboard</a><a class="btn outline sm" href="#/browse">Browse companies</a></div></div></div>`; }
// Staff passcode gate for #/staff/<role>.
function viewStaffGate(main, role) {
  if (!D.ROLES[role] || role === 'client') return viewNotFound(main);
  if (D.role() === role) { go('#/admin'); return; }
  main.innerHTML = `<div class="page narrow" style="max-width:520px"><form class="card gate" id="staff-gate"><div class="card-head"><span class="row" style="gap:10px"><span class="gate-lock">${LOCK}</span><h2 style="font-size:20px">Staff access · ${esc(D.ROLES[role])}</h2></span></div><div class="card-body stack">
    <p class="small muted" style="margin:0">This area holds client, order and compliance records. Access is limited to authorized Rainmaker personnel and every entry is logged.</p>
    <div class="field"><label>Staff passcode</label><input name="code" type="password" autocomplete="off" required placeholder="••••••••"></div>
    <div class="tiny down" id="gate-err"></div>
    <ul class="small muted" style="margin:0;padding-left:18px"><li>The session lives in this tab only and locks after ${Math.round(D.STAFF_IDLE_MS / 60000)} minutes idle.</li><li>Every sign-in, lock, approval and failed attempt is written to the audit log.</li><li>Staff pages are hidden from members and visitors and answer "not found".</li></ul>
    <div class="callout tiny">Prototype passcode: <b>${esc(RX_CONFIG.staff.demoPasscode)}</b>. At launch this is replaced by staff identity with MFA on Rainmaker's servers, and no staff data is sent to a member's browser.</div>
  </div><div class="card-foot form-foot" style="background:#fff"><button class="btn" type="submit">Enter ${esc(D.ROLES[role])} view</button><a class="btn ghost" href="#/dashboard">Cancel</a></div></form></div>`;
  const f = main.querySelector('#staff-gate'); setTimeout(() => f.code.focus(), 0);
  f.addEventListener('submit', e => { e.preventDefault(); const r = D.staffSignIn(role, f.code.value); if (r.error) { main.querySelector('#gate-err').textContent = r.error; f.code.value = ''; f.code.focus(); return; } toast(`Switched to ${D.ROLES[role]} view`); go('#/admin'); });
}

// Back-office tabs: [id, label, permission needed].
const ADMIN_TABS = [['overview', 'Overview'], ['verifications', 'Verifications', 'verifications'], ['requests', 'Requests', 'requests'], ['orders', 'Orders', 'orders.view'], ['matches', 'Matches', 'matches'], ['companies', 'Companies', 'companies'], ['inbox', 'Messages', 'inbox'], ['mailbox', 'Rainmaker mailbox', 'inbox'], ['clients', 'Clients', 'clients'], ['forms', 'Compliance forms', 'forms'], ['audit', 'Activity log', 'audit']];
// Every back-office page is titled by what it is (Orders, Compliance forms, …), never "Console" (Ben, Sep 25 2026).
const ADMIN_META = {
  overview: { t: 'Overview', icon: () => PH.console, sub: 'Everything clients submit lands here: verifications, forms, requests, orders, settlements and messages.' },
  verifications: { t: 'Verifications', icon: () => PH.verify, sub: 'Investor status reviews. Approving a client places their pending requests on the book.' },
  forms: { t: 'Compliance forms', icon: () => PH.forms, sub: 'Accreditation, KYC, tax, subscription, term-sheet and transfer paperwork awaiting a decision.' },
  requests: { t: 'Requests', icon: () => PH.requests, sub: 'Orders submitted by members who are not yet verified, plus structured deals in the desk pipeline.' },
  mailbox: { t: 'Rainmaker mailbox', icon: () => PH.mail, sub: 'Rainmaker Securities as a correspondent: what members send to the firm (support and operations, not to a representative) and what the firm sends out. Representatives\' conversations are monitored under Messages.' },
  orders: { t: 'Orders', icon: () => PH.orders, sub: 'Every bid, ask, custom order and structured deal on the exchange, newest first. Orders carry no settlement state: when two cross, the match appears under Matches and settles there.' },
  matches: { t: 'Matches', icon: () => PH.settle, sub: 'Every clearance event: a buyer and a seller whose orders crossed. Approve a match to notify both parties and open the settlement; open one to record signatures, the broker fee and each closing step.' },
  companies: { t: 'Companies', icon: () => PH.companies, sub: 'Listed companies, transfer policies and fees.' },
  inbox: { t: 'Messages', icon: () => PH.mail, sub: 'Every message from every member, monitored by Rainmaker. Filter by user, representative or sender, or search by keyword.' },
  clients: { t: 'Clients', icon: () => PH.clients, sub: 'The client book: status, representative, assets and activity.' },
  audit: { t: 'Activity log', icon: () => PH.audit, sub: 'Everything that happens on the exchange, newest first: orders, matches, settlements, approvals, staff sessions, messages, exports. Filter by kind, actor, period or keyword.' },
};
// ---- shared filter bar for the back-office tabs. State lives in D.state.adminF[tab]; every list defaults to newest entered first.
function afState(tab, defaults) { const S = D.state.adminF || (D.state.adminF = {}); if (!S[tab]) S[tab] = Object.assign({}, defaults); else Object.keys(defaults).forEach(k => { if (S[tab][k] === undefined) S[tab][k] = defaults[k]; }); return S[tab]; }
// Render the shared back-office filter bar from a field list.
function afBar(F, fields) {
  const opt = (v, l, cur) => `<option value="${esc(String(v))}" ${String(cur) === String(v) ? 'selected' : ''}>${esc(l)}</option>`;
  return `<div class="af-bar">${fields.map(f => f.q != null ? `<input class="mini" data-afq="${f.k}" placeholder="${esc(f.q)}" value="${esc(F[f.k] || '')}" style="width:${f.w || 200}px">` : f.date ? `<label class="af-date" title="${esc(f.title || '')}"><span>${esc(f.date)}</span><input class="mini" type="date" data-afd="${f.k}" value="${esc(F[f.k] || '')}"></label>` : `<select class="mini" data-afs="${f.k}" title="${esc(f.title || '')}">${f.sel.map(([v, l]) => opt(v, l, F[f.k])).join('')}</select>`).join('')}<button class="btn ghost xs" type="button" data-af-clear>Clear</button></div>`;
}
// Hook the filter bar up: write to state.adminF[tab] and re-render.
function wireAf(main, tab, defaults, redraw) {
  const bar = main.querySelector('.af-bar'); if (!bar) return; const F = afState(tab, defaults); const draw = redraw || (() => viewAdmin(main, tab));   // member pages (Market activity) pass their own redraw
  bar.querySelectorAll('[data-afs]').forEach(s => s.onchange = () => { F[s.dataset.afs] = s.value; draw(); });
  bar.querySelectorAll('[data-afd]').forEach(d => d.onchange = () => { F[d.dataset.afd] = d.value; draw(); });   // date inputs: "placed between" (Ben, Oct 1 2026)
  bar.querySelectorAll('[data-afq]').forEach(q => q.addEventListener('input', () => { F[q.dataset.afq] = q.value; const pos = q.selectionStart; draw(); const n = main.querySelector(`[data-afq="${q.dataset.afq}"]`); if (n) { n.focus(); n.setSelectionRange(pos, pos); } }));
  const cl = bar.querySelector('[data-af-clear]'); if (cl) cl.onclick = () => { D.state.adminF[tab] = Object.assign({}, defaults); draw(); };
}
// Case-insensitive keyword match across several values.
const afHas = (q, ...vals) => { q = (q || '').trim().toLowerCase(); return !q || vals.some(v => String(v == null ? '' : v).toLowerCase().includes(q)); };
// Sort a list by the chosen key using the getter map.
const afSort = (list, key, g) => list.slice().sort((a, b) => { const f = g[key] || g.newest; const va = f(a), vb = f(b); return typeof va === 'string' ? va.localeCompare(vb) : va - vb; });
// Representative select options.
const repOpts = () => [['all', 'All representatives']].concat(D.REPS.map(r => [r.id, r.name]));
// Company select options, A–Z.
const coOpts = () => [['all', 'All companies']].concat(D.COMPANIES.slice().sort((a, b) => a.name.localeCompare(b.name)).map(c => [c.id, c.name]));
// Settlement status badge.
const stlBadge = s => s ? `<span class="badge ${s === 'Complete' ? 'verified' : 'pending'}">${s}</span>` : '<span class="dim small">—</span>';
// Representative as "First L.".
const repShort = id => { const r = D.rep(id); return r ? esc(r.name.split(' ')[0] + ' ' + r.name.split(' ').slice(-1)[0][0] + '.') : '—'; };
// Whether the New company / Record order forms are open.
let adminNewCo = false; let adminNewOrder = false; let adminNewMail = false;   // compose forms open / closed (Record order, Rainmaker mailbox)
// Orders tab bulk selection (Ben, Oct 1 2026): ids ticked on the Orders list and whether the inline "Remove selected" confirmation is open. Not persisted.
let ordSel = new Set(); let ordRmOpen = false;
// Client select options, A–Z (the member session first).
const clientOpts = () => [['all', 'All clients']].concat(D.clientsList().slice().sort((a, b) => (a.you ? -1 : b.you ? 1 : a.name.localeCompare(b.name))).map(k => [k.id, k.name + (k.you ? ' (member session)' : '')]));
// ---- export buttons (data-export="orders-csv" etc.). The Data layer checks permissions and audits each export.
const EXPORTS = {
  'orders-csv': () => { const r = D.exportOrders(); return r.error ? r : { name: exportName('orders', 'csv'), text: D.toCSV(r.rows, r.columns), mime: 'text/csv', n: r.rows.length, what: 'orders' }; },
  'orders-json': () => { const r = D.exportOrders(); return r.error ? r : { name: exportName('orders', 'json'), text: JSON.stringify(r.rows, null, 2), mime: 'application/json', n: r.rows.length, what: 'orders' }; },
  'forms-csv': () => { const r = D.exportForms(); return r.error ? r : { name: exportName('compliance-forms', 'csv'), text: D.toCSV(r.rows, r.columns), mime: 'text/csv', n: r.rows.length, what: 'forms' }; },
  'forms-json': () => { const r = D.exportForms(); return r.error ? r : { name: exportName('compliance-forms', 'json'), text: JSON.stringify(r.rows, null, 2), mime: 'application/json', n: r.rows.length, what: 'forms' }; },
  'matches-csv': () => { const r = D.exportMatches(); return r.error ? r : { name: exportName('matches', 'csv'), text: D.toCSV(r.rows, r.columns), mime: 'text/csv', n: r.rows.length, what: 'matches' }; },
  'matches-json': () => { const r = D.exportMatches(); return r.error ? r : { name: exportName('matches', 'json'), text: JSON.stringify(r.rows, null, 2), mime: 'application/json', n: r.rows.length, what: 'matches' }; },
  'all-json': () => { const b = D.exportBundle(); return b.error ? b : { name: exportName('all-records', 'json'), text: JSON.stringify(b, null, 2), mime: 'application/json', n: b.counts.orders + b.counts.forms, what: 'records' }; },
};
function wireExports(root) {
  root.querySelectorAll('[data-export]').forEach(btn => btn.onclick = () => {
    const make = EXPORTS[btn.dataset.export]; if (!make) return;
    const r = make(); if (r.error) { toast(r.error, false); return; }
    downloadFile(r.name, r.text, r.mime); toast(`${r.n} ${r.what} downloaded (${r.name})`);
  });
}
// Fee rate as a percentage string.
function feePct(r) { const v = r * 100; return (v % 1 ? v.toFixed(2) : v.toFixed(0)) + '%'; }
// Settlement card for the Console: tracker, contract signatures from both sides, broker fees (adjustable per deal), documents.
function settlementPanel(x) {
  const c = D.company(x.companyId); const done = D.settlementDone(x); const p = x.parties || {}; const f = D.settlementFees(x); const kind = D.settleKind(x);
  const buyerName = x.side === 'buy' ? D.profile().name : (kind === 'desk' ? 'Rainmaker desk (principal)' : 'Buyer · brokered'); const sellerName = x.side === 'sell' ? D.profile().name : (kind === 'desk' ? 'Rainmaker desk (principal)' : 'Seller · brokered');
  const sigRow = (who, name, ts) => `<div class="prow"><span><b>${who}</b> <span class="muted">· ${esc(name)}</span></span>${ts ? `<span class="badge verified">Signed ${fmtDateShort(ts)}</span>` : `<button class="btn outline sm" data-stl-mark="${x.id}" data-what="${who.toLowerCase()}">Record ${who.toLowerCase()} signature</button>`}</div>`;
  return `<div class="pipe-row" id="stl-${esc(x.id)}"><div class="between" style="margin-bottom:8px;flex-wrap:wrap;gap:8px"><span class="row">${logo(c, 'sm')}<b>${esc(c.name)}</b><span class="muted small">${x.side === 'buy' ? 'Client buys' : 'Client sells'} ${num(x.qty)} @ ${money(x.price)} · ${money(x.gross, 0)} gross · ${kind === 'desk' ? 'desk' : 'exchange match'}</span></span><span class="row" style="gap:10px">${stlBadge(D.settlementStatus(x))}<span class="muted small">Entered ${fmtPlaced(x.ts)} · rep ${repShort(D.assignedRep({ mine: true }))}</span></span></div>
    ${trackerBlock(x, { compact: true })}
    <div class="stl-grid"><div class="stl-box"><span class="label dim">Contract signatures</span><div class="tiny muted" style="margin-bottom:4px">Rainmaker has both sides sign the stock transfer agreement before any money moves.</div>${sigRow('Buyer', buyerName, p.buyer)}${sigRow('Seller', sellerName, p.seller)}</div>
    <div class="stl-box"><span class="label dim">Broker fees</span><div class="tiny muted" style="margin-bottom:4px">Default 3% buy side · 2% sell side (min ${money(D.FEES.brokerageMin, 0)}). Adjust per deal.</div>
      <form class="fee-form" data-stl-fee-form="${esc(x.id)}"><div class="field"><label>Buy side %</label><input class="mini" name="buy" type="number" step="0.25" min="0" max="20" value="${(f.buyRate * 100).toFixed(2).replace(/\.?0+$/, '')}" ${p.fees ? 'disabled' : ''}></div><div class="field"><label>Sell side %</label><input class="mini" name="sell" type="number" step="0.25" min="0" max="20" value="${(f.sellRate * 100).toFixed(2).replace(/\.?0+$/, '')}" ${p.fees ? 'disabled' : ''}></div>${p.fees ? '' : '<button class="btn ghost sm" type="submit">Save rates</button>'}</form>
      <div class="prow"><span>Buyer pays <b>${money(f.buy, 0)}</b> · seller pays <b>${money(f.sell, 0)}</b> · total <b>${money(f.total, 0)}</b>${f.custom ? ' <span class="badge custom">Adjusted</span>' : ''}</span>${p.fees ? `<span class="badge verified">Paid ${fmtDateShort(p.fees)}</span>` : `<button class="btn outline sm" data-stl-mark="${x.id}" data-what="fees">Record fee payment</button>`}</div></div></div>
    ${docsBlock(x)}<div class="between" style="margin-top:8px"><span class="tiny muted">${done ? 'Closed ' + fmtDate(x.steps[D.settleSteps(x).length - 1] || x.ts) : 'Next: ' + esc(D.settleSteps(x)[x.stage + 1] || '')}</span>${done ? '<span class="badge verified">Complete</span>' : `<button class="btn outline sm" data-advance="${x.id}">Mark next step done</button>`}</div></div>`;
}
// Hook up the per-deal broker fee forms on settlement panels.
function wireFeeForms(root) { root.querySelectorAll('[data-stl-fee-form]').forEach(f => f.addEventListener('submit', e => { e.preventDefault(); const r = D.setSettlementFees(f.dataset.stlFeeForm, (+f.buy.value || 0) / 100, (+f.sell.value || 0) / 100); if (r.error) { toast(r.error, false); return; } toast('Broker fee rates saved for this deal'); const y = window.scrollY; render(); window.scrollTo(0, y); })); }
