    w.innerHTML = `<form class="card" id="ord-edit" style="margin-bottom:18px"><div class="card-head"><span class="label">Edit ${esc(r.id)} · ${r.side === 'ask' ? 'ask' : 'bid'} · ${esc(r.c ? r.c.name : '')} · ${esc(r.cl.name)}</span><button class="btn ghost sm" type="button" id="ord-edit-x">Close</button></div><div class="card-body stack" style="gap:10px">
      <div class="grid-3"><div class="field"><label>Shares</label><input name="qty" type="number" min="${o ? 1 : 0}" step="1" value="${r.qty || ''}"></div><div class="field"><label>${priceLbl}</label><input name="price" type="number" min="0" step="0.01" value="${r.price || ''}"></div>${o ? `<div class="field"><label>Valid for (days from today)</label><input name="days" type="number" min="1" value="${days}"></div>` : '<div></div>'}</div>
      ${o ? `<div class="grid-3"><div class="field"><label>Share class</label>${sel('shareType', ['Common', 'Preferred'], o.shareType)}</div><div class="field"><label>Transfer type</label>${sel('transferType', ['Direct', 'SPV', 'Forward'], o.transferType)}</div></div><div class="grid-3"><div class="field"><label>Order type</label><select name="fill">${Object.entries(D.FILL_RULES).map(([k, l]) => `<option value="${k}"${D.fillRule(o).fill === k ? ' selected' : ''}>${l}</option>`).join('')}</select></div><div class="field ord-min ${D.fillRule(o).fill === 'min' ? '' : 'hidden'}"><label>Minimum shares per fill</label><input name="minFill" type="number" min="1" step="1" value="${D.fillRule(o).min || ''}"></div></div>` : `<div class="field"><label>Terms (as shown to the desk and the client)</label><textarea name="what" style="height:70px">${esc(a.what || '')}</textarea></div>`}
      <div class="field"><label>Note (kept on the order)</label><input name="note" value="${esc(o ? o.note || (o.recorded && o.recorded.note) || '' : a.note || '')}"></div>
      <div class="small muted">Client, company and side cannot be changed here: remove the order and record it again. Every change is audited as ${esc(D.ROLES[role])}${r.cl.id === 'you' ? ' and the client is notified' : ''}.</div></div>
      <div class="card-foot form-foot" style="background:#fff"><button class="btn" type="submit">Save changes</button><button class="btn danger" type="button" data-ord-rm="${esc(r.id)}" style="margin-left:8px">Remove from book</button></div></form>`;
    w.querySelector('[data-ord-rm]').onclick = () => { ordSel = new Set([r.id]); ordRmOpen = true; viewAdmin(main, 'orders'); };
