    w.querySelector('#ord-edit').addEventListener('submit', e => { e.preventDefault(); const f = e.target; const res = D.updateOrder(r.id, { qty: f.qty.value, price: f.price.value, days: f.days ? f.days.value : '', shareType: f.shareType ? f.shareType.value : '', transferType: f.transferType ? f.transferType.value : '', fill: f.fill ? f.fill.value : '', minFill: f.minFill ? f.minFill.value : '', what: f.what ? f.what.value : null, note: f.note.value.trim() }); if (res.error) { toast(res.error, false); return; } toast(`${r.id} updated: ${res.changes.join(', ')}`); viewAdmin(main, 'orders'); });
